import math
def file_budget(values,process_soft_limit):
 allocated=values.get('node_filefd_allocated');maximum=values.get('node_filefd_maximum')
 if allocated is None or maximum is None or maximum<=0:return dict(status='unknown',ratio=None,headroom=None,process_soft_limit=process_soft_limit)
 if any(type(value) not in (int,float) or not math.isfinite(value) or value<0 or not float(value).is_integer() for value in (allocated,maximum)):raise ValueError('nonnegative finite integral system counters required')
 return dict(status='over_limit' if allocated>maximum else 'ok',ratio=allocated/maximum,headroom=max(0,maximum-allocated),process_soft_limit=process_soft_limit)
```

